def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = sum(1 for x in op if x == 'D')
    opp_c = n - opp_d
    my_d = sum(1 for x in my if x == 'D')

    last_me, last_op = history[-1]
    rem = 100 - n
    rate = opp_d / n

    r10 = op[-10:] if n >= 10 else op
    r10d = sum(1 for x in r10 if x == 'D')

    streak = 0
    for x in reversed(op):
        if x == 'D':
            streak += 1
        else:
            break

    copy = 0
    afterDC = 0
    afterDD = 0
    afterCC = 0
    afterCD = 0

    for i in range(1, n):
        pm = my[i - 1]
        co = op[i]
        if pm == co:
            copy += 1
        if pm == 'D':
            if co == 'C':
                afterDC += 1
            else:
                afterDD += 1
        else:
            if co == 'C':
                afterCC += 1
            else:
                afterCD += 1

    trans = n - 1
    copy_rate = copy / trans if trans > 0 else 1.0
    afterD = afterDC + afterDD
    pD = afterDC / afterD if afterD > 0 else -1.0

    if afterD > 0:
        responsive_punish = (pD < 0.5 and afterDD > afterDC) or (copy_rate >= 0.75 and afterDD >= afterDC)
    else:
        responsive_punish = copy_rate >= 0.75

    period = 0
    for p in (2, 3, 4, 5):
        if n >= 3 * p:
            if op[-p:] == op[-2 * p:-p] and op[-p:] == op[-3 * p:-2 * p]:
                period = p
                break

    can_break = (
        opp_c > 0
        and opp_c >= 2
        and copy_rate >= 0.75
        and afterCC > afterCD
        and rate <= 0.97
    )

    if rem <= 1:
        return 'D'

    if opp_c == 0:
        if opp_d >= 25 and rng.random() < 0.01:
            return 'C'
        return 'D'

    if opp_d == 0:
        if afterDD == 0 and afterDC > 0:
            return 'D'
        if last_me == 'D':
            return 'C'
        if n >= 20:
            return 'D'
        return 'C'

    if period > 0 and rate > 0.15 and rem > 2 and not responsive_punish and not can_break:
        return 'D'

    if (rate > 0.65 or (r10d >= 8 and opp_c * 2 < n) or (streak >= 6 and opp_c < 3)) and not can_break:
        return 'D'

    if last_op == 'C':
        if rem > 5 and my_d == 0 and n >= 20 and opp_d <= 6 and opp_c >= opp_d * 3:
            return 'D'

        if rem > 1 and opp_c >= opp_d and rate <= 0.55 and afterDC > afterDD:
            return 'D'

        if rem > 3 and 0.35 <= rate <= 0.65 and not responsive_punish:
            if pD >= 0.5 or period > 0 or my_d == 0 or afterDC > 0:
                return 'D'
    else:
        if last_me == 'D' and copy_rate >= 0.7 and opp_c >= opp_d and rate <= 0.55:
            return 'C'

        if last_me == 'D' and can_break and rate > 0.65 and rem > 5:
            return 'C'

        if opp_c >= opp_d and rate <= 0.35 and rem > 1:
            return 'C'

        return 'D'

    return 'C'
